import type { InstrumentId } from '../instruments'

// Lessons are plain JSON-compatible data so they can later be stored in a database
// and edited (or generated by Claude) from the admin panel.

export interface InfoStep {
  kind: 'info'
  title?: string
  text: string
}

export interface NotesStep {
  kind: 'notes'
  /** What to tell the learner, e.g. "Play C, D, E going up". */
  instruction: string
  /** Notes to play in order, as labels like "C4", "F#3". */
  notes: string[]
  /** Optional lyric or finger hint shown under each note (same length as notes). */
  hints?: string[]
}

export type LessonStep = InfoStep | NotesStep

export interface Lesson {
  id: string
  instrument: InstrumentId
  title: string
  description: string
  level: 1 | 2 | 3
  steps: LessonStep[]
}
